run_check "INVARIANT" bash -lc 'rg -U -n "^@\[inline\] def pipChainStart_replyRecv\b[^\n]*(\n([ \t][^\n]*)?)*some recordedServerTid" SeLe4n/Kernel/Concurrency/Locks/LockSetTransitions.lean'
