import SeLe4n.Platform.DeviceTree
import SeLe4n.Kernel.Scheduler.PriorityInheritance.ChainFootprint
#check @SeLe4n.Platform.FdtNode.statusIsOperational
#check @SeLe4n.Platform.FdtNode.isMemoryNode
