run_check "INVARIANT" rg -n '^def timeoutFrame($|[ ({:\[\]])' SeLe4n/Kernel/Architecture/SyscallReturn.lean
run_check "INVARIANT" rg -n '^def cancelledIpcFrame($|[ ({:\[\]])' SeLe4n/Kernel/Architecture/SyscallReturn.lean
