run_check "INVARIANT" rg -n '^private def liveWithTaint($|[ ({:\[\]])' tests/FrozenOpsSuite.lean
run_check "INVARIANT" rg -n 'differentialTaintedSignalAgrees' tests/FrozenOpsSuite.lean
