run_negative_check "INVARIANT" bash -lc 'rg -U -n "^def frozenApplyReplyDonation[^\n]*(\n([ \t][^\n]*)?)*if originalOwner\.isReserved then" SeLe4n/Kernel/FrozenOps/Operations.lean'
