run_negative_check "INVARIANT" bash -lc 'rg -U -n "^def donationOwnerFlowsToHolder[^\n]*(\n([ \t][^\n]*)?)*schedContextBinding = .donated" SeLe4n/Kernel/InformationFlow/Invariant/Composition.lean'
