run_check "INVARIANT" bash -lc 'rg -U -n "errors = check_fixture_index\(directory, readme\)\n        consumer_errors, claims = check_fixture_consumers\(directory, readme\)\n        errors \+= consumer_errors" scripts/scenario_catalog.py'
