run_check "INVARIANT" bash -lc 'rg -U -n "^def frozenWriteTcbBoundPlaced[^\n]*(\n([ \t][^\n]*)?)*frozenRebucketRunnable st. tid after.boostedPriority" SeLe4n/Kernel/FrozenOps/Core.lean'
