run_check "INVARIANT" bash -lc 'rg -U -n "^def bindPlacesParkedThread \(st : SystemState\)[^\n]*(\n([ \t][^\n]*)?)*    && sc.budgetRemaining.isPositive" SeLe4n/Kernel/SchedContext/Operations.lean'
